package behavioral.visitor.sample;

public interface IProduct {
    void accept(IProductVisitor visitor);
}

package behavioral.visitor.sample;

import behavioral.visitor.sample.products.Book;
import behavioral.visitor.sample.products.Electronics;

public interface IProductVisitor {
    void visit(Book book);
    void visit(Electronics electronics);
}

package behavioral.visitor.sample;

import behavioral.visitor.sample.products.*;
import behavioral.visitor.sample.visitors.*;

public class Main {

    public static void main(String[] args) {
        IProduct book = new Book(1000);
        IProduct laptop = new Electronics(50000);

        IProductVisitor taxVisitor = new TaxVisitor();
        book.accept(taxVisitor);
        laptop.accept(taxVisitor);

        IProductVisitor discountVisitor = new DiscountVisitor();
        book.accept(discountVisitor);
        laptop.accept(discountVisitor);
    }
}

package behavioral.visitor.sample.products;

import behavioral.visitor.sample.IProduct;
import behavioral.visitor.sample.IProductVisitor;

public class Book implements IProduct {
    private final double price;

    public Book(double price) {
        this.price = price;
    }

    public double getPrice() {
        return price;
    }

    @Override
    public void accept(IProductVisitor visitor) {
        visitor.visit(this);
    }
}

package behavioral.visitor.sample.products;

import behavioral.visitor.sample.IProduct;
import behavioral.visitor.sample.IProductVisitor;

public class Electronics implements IProduct {
    private final double price;

    public Electronics(double price) {
        this.price = price;
    }

    public double getPrice() {
        return price;
    }

    @Override
    public void accept(IProductVisitor visitor) {
        visitor.visit(this);
    }
}

package behavioral.visitor.sample.visitors;

import behavioral.visitor.sample.products.Book;
import behavioral.visitor.sample.products.Electronics;
import behavioral.visitor.sample.IProductVisitor;

public class DiscountVisitor implements IProductVisitor {
    @Override
    public void visit(Book book) {
        System.out.println("Book discount: " + book.getPrice() * 0.10);
    }

    @Override
    public void visit(Electronics electronics) {
        System.out.println("Electronics discount: " + electronics.getPrice() * 0.20);
    }
}

package behavioral.visitor.sample.visitors;

import behavioral.visitor.sample.IProductVisitor;
import behavioral.visitor.sample.products.Book;
import behavioral.visitor.sample.products.Electronics;

public class TaxVisitor implements IProductVisitor {
    @Override
    public void visit(Book book) {
        double tax = book.getPrice() * 0.05;
        System.out.println("Book tax: " + tax);
    }

    @Override
    public void visit(Electronics electronics) {
        double tax = electronics.getPrice() * 0.18;
        System.out.println("Electronics tax: " + tax);
    }
}

